  match r, t with
  | 1, (StA, S1) => [SWin 2;SCycL 2 0;SWinL 4;SCycR 2;SWin 1]
  | 1, (StB, S0) => []
  | 1, (StB, S1) => [SWin 2;SCycL 2 0;SWinL 4]
  | 1, (StC, S0) => [SWin 1]
  | 1, (StC, S1) => [SWin 2;SCycL 2 0;SWinL 3]
  | 1, (StD, S0) => [SWin 2;SCycL 2 0;SWinL 2]
  | 1, (StD, S1) => [SWin 2]
  | _, _ => []
  end.

