  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0;S1] [S1;S0;S1] 1 0 [S0;S0;S0]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0;S0] [S0;S0;S0] 1 0 [S1;S0;S0])) 6 8.
Definition ch_iarm0_1_1RB1RC_0LB1RC_1LD1RA_0RC0LD : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWin 2);RB (SCycL 3 0);RB (SWin 3)].
