  | 0, 0 => iarm0_0_1RB1RD_1LC0RD_1RA1LB_0LB0RA
  | 0, 1 => iarm0_1_1RB1RD_1LC0RD_1RA1LB_0LB0RA
  | 1, 0 => iarm1_0_1RB1RD_1LC0RD_1RA1LB_0LB0RA
  | 1, 1 => iarm1_1_1RB1RD_1LC0RD_1RA1LB_0LB0RA
  | 2, 0 => iarm2_0_1RB1RD_1LC0RD_1RA1LB_0LB0RA
  | 2, 1 => iarm2_1_1RB1RD_1LC0RD_1RA1LB_0LB0RA
  | _, _ => iarm0_0_1RB1RD_1LC0RD_1RA1LB_0LB0RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

